using Xunit;

public class CalculadoraTests
{
    [Fact]
    public void Somar_DoisNumeros_RetornaSoma()
    {
        var calc = new Calculadora();
        Assert.Equal(5, calc.Somar(2, 3));
    }

    [Theory]
    [InlineData(2, true)]
    [InlineData(3, false)]
    public void EhPar_ValoresVariados_RetornaEsperado(int n, bool esperado)
    {
        Assert.Equal(esperado, n % 2 == 0);
    }
}

